// Sources checked 22 October 2026. These are general education, not a symptom forecast.
// Facts deliberately avoid cigarette-only carbon monoxide / lung recovery milestones.
const JOURNEY_FACTS = [
  {id:'withdrawal-adjustment',fromDay:0,tag:'WHAT IS HAPPENING',title:'The brain is changing its routine.',text:'Withdrawal is your body adjusting to less nicotine. Irritability, restlessness, poor concentration and cravings can happen; people experience them differently.',url:'https://smokefree.gov/challenges-when-quitting/withdrawal/managing-nicotine-withdrawal',source:'Smokefree / National Cancer Institute'},
  {id:'wave-not-clock',fromDay:0,tag:'CRAVING TOOL',title:'An urge is not a countdown contract.',text:'Individual nicotine cravings often ease after a few minutes. A five-minute pause is a coping tool, not a guarantee that your urge ends on the buzzer.',url:'https://www2.hse.ie/living-well/quit-smoking/get-help-to-quit/cravings-withdrawal/',source:'HSE Ireland'},
  {id:'five-ds',fromDay:0,tag:'TRY THIS',title:'Deploy the extremely boring superpowers.',text:'Delay, distract yourself, breathe slowly, drink water, and discuss the craving with a friend. These are practical ways to ride out an urge.',url:'https://www.canada.ca/en/health-canada/services/smoking-tobacco/vaping/quitting.html',source:'Health Canada'},
  {id:'hands-busy',fromDay:0,tag:'SIDE QUEST',title:'Give your hands another job.',text:'A short game, puzzle or small task can redirect your attention during a craving. Keep a distraction ready before the next urge arrives.',url:'https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/understand-your-smoking-triggers-and-cravings/',source:'NHS Better Health'},
  {id:'early-start',fromDay:0.25,tag:'FIRST DAY',title:'The first shift can be loud.',text:'Cravings may start within an hour or two after the last use of tobacco. Frequent early urges do not mean your attempt is going badly.',url:'https://www.cancer.gov/about-cancer/causes-prevention/risk/tobacco/withdrawal-fact-sheet',source:'National Cancer Institute'},
  {id:'appetite',fromDay:1,tag:'SNACK DEPARTMENT',title:'The snack department may be hiring.',text:'Feeling hungrier can be part of nicotine withdrawal. Keep easy snacks nearby; something crunchy can also give your hands and mouth another task.',url:'https://smokefree.gov/quit-vaping-resources/nicotine-withdrawal-vaping',source:'Smokefree / National Cancer Institute'},
  {id:'concentration',fromDay:1,tag:'BRAIN BUFFERING',title:'Your brain may have extra loading screens.',text:'Trouble concentrating can occur during nicotine withdrawal. Break a task into smaller pieces and give yourself room for a slower day.',url:'https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/managing-nicotine-withdrawal-symptoms/',source:'NHS Better Health'},
  {id:'peak-first-days',fromDay:2,tag:'EARLY DAYS',title:'A difficult day is still a day of progress.',text:'Nicotine withdrawal is usually toughest in the first week and often peaks during the first three days. This is a common pattern, not a deadline.',url:'https://www.cancer.gov/about-cancer/causes-prevention/risk/tobacco/withdrawal-fact-sheet',source:'National Cancer Institute'},
  {id:'sleep',fromDay:2,tag:'REST QUEST',title:'Sleep is legitimate raid preparation.',text:'Feeling tired or having trouble sleeping can happen when quitting nicotine vaping. A consistent sleep routine may help while your body adjusts.',url:'https://smokefree.gov/quit-vaping-resources/nicotine-withdrawal-vaping',source:'Smokefree / National Cancer Institute'},
  {id:'triggers',fromDay:3,tag:'PATTERN SPOTTING',title:'The kiosk is a trigger, not a prophecy.',text:'Routines, places, people and emotions can trigger cravings. Noticing your own pattern lets you plan a different route or activity next time.',url:'https://www.canada.ca/en/health-canada/services/smoking-tobacco/vaping/quitting.html',source:'Health Canada'},
  {id:'buddy',fromDay:4,tag:'PARTY BONUS',title:'Tell the squad what backup looks like.',text:'Ask friends for a specific kind of support: a distraction, a quick chat, or keeping nicotine products away from you. They cannot read goblin minds.',url:'https://www.canada.ca/en/health-canada/services/smoking-tobacco/vaping/quitting.html',source:'Health Canada'},
  {id:'individual-pace',fromDay:5,tag:'NO FIXED SCHEDULE',title:'You do not owe the app a perfect mood.',text:'Withdrawal varies between people. A hard day beside someone else\'s easy day is not a lower score or a sign that you are doing this wrong.',url:'https://smokefree.gov/challenges-when-quitting/withdrawal/managing-nicotine-withdrawal',source:'Smokefree / National Cancer Institute'},
  {id:'week-review',fromDay:7,tag:'WEEK ONE',title:'Audit the tricks that actually helped.',text:'Look back at your triggers and which distractions worked. Keep the useful ones ready for your next craving instead of relying on memory alone.',url:'https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/understand-your-smoking-triggers-and-cravings/',source:'NHS Better Health'},
  {id:'mood',fromDay:10,tag:'CHECK IN',title:'Do not solo the difficult stuff.',text:'Mood changes can happen during withdrawal. If sadness is severe or worrying, tell someone you trust and speak with a healthcare professional.',url:'https://smokefree.gov/quit-vaping-resources/nicotine-withdrawal-vaping',source:'Smokefree / National Cancer Institute'},
  {id:'month-pattern',fromDay:14,tag:'WEEKS TWO TO FOUR',title:'The volume often starts coming down.',text:'Withdrawal symptoms commonly become less intense over the first month. Some people take longer; the app cannot predict your personal recovery.',url:'https://www.cancer.gov/about-cancer/causes-prevention/risk/tobacco/withdrawal-fact-sheet',source:'National Cancer Institute'},
  {id:'support-options',fromDay:21,tag:'EXTRA TOOLS',title:'Asking for help is an allowed strategy.',text:'A healthcare professional can discuss ways to manage nicotine cravings and withdrawal. You can get support at any stage of quitting.',url:'https://www.cdc.gov/tobacco/e-cigarettes/quitting.html',source:'US Centers for Disease Control and Prevention'},
  {id:'not-finished-clock',fromDay:28,tag:'FOUR WEEKS',title:'There is no mandatory finish line for symptoms.',text:'Many people find withdrawal eases over several weeks. If symptoms persist, do not improve, or worry you, speak with a healthcare professional.',url:'https://www2.hse.ie/living-well/quit-smoking/get-help-to-quit/cravings-withdrawal/',source:'HSE Ireland'},
  {id:'later-cravings',fromDay:60,tag:'LONG GAME',title:'A surprise craving does not erase the run.',text:'Triggers can bring back an occasional craving long after quitting. Keep a coping plan available even when nicotine rarely crosses your mind.',url:'https://www.cancer.gov/about-cancer/causes-prevention/risk/tobacco/withdrawal-fact-sheet',source:'National Cancer Institute'}
];


