 function background(ctx,w,h,time=0,theme='forest'){
  const gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,theme==='relief'?'#172931':'#142a28');gradient.addColorStop(.5,'#152923');gradient.addColorStop(1,'#101e1a');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);
  // Far tree silhouettes, wandering paths, soft shafts of light and fireflies.
  for(let layer=0;layer<3;layer++){ctx.fillStyle=['#12312c','#163c31','#203f31'][layer];for(let i=0;i<8;i++){const x=((i*139+layer*47)%Math.round(w+100))-45,y=((i*93+time*(9+layer*8))%(h+220))-150;ctx.beginPath();ctx.moveTo(x,y+200);ctx.bezierCurveTo(x+15,y+100,x-22,y+60,x+5,y);ctx.bezierCurveTo(x+20,y+40,x+17,y+90,x+37,y+190);ctx.closePath();ctx.fill();}}
  ctx.fillStyle='#71885b10';ctx.beginPath();ctx.moveTo(w*.44,0);ctx.bezierCurveTo(w*.14,h*.3,w*.72,h*.5,w*.14,h);ctx.lineTo(w*.9,h);ctx.bezierCurveTo(w*.36,h*.45,w*.78,h*.3,w*.61,0);ctx.fill();
  ctx.save();ctx.globalCompositeOperation='screen';for(let i=0;i<4;i++){ctx.fillStyle='#b6e69e05';ctx.beginPath();ctx.moveTo(w*.12+i*110,-20);ctx.lineTo(w*.5+i*70,h);ctx.lineTo(w*.7+i*70,h);ctx.closePath();ctx.fill();}ctx.restore();
  for(let i=0;i<22;i++){const x=(i*83+Math.sin(time*.45+i)*20)%w,y=(i*127+time*7)%(h+20);ctx.fillStyle=i%3?'#ddde8960':'#9ceac489';ctx.beginPath();ctx.arc(x,y,1+Math.sin(time+i)*.5,0,7);ctx.fill();}
  for(let i=0;i<7;i++){const y=((i*149+time*22)%(h+140))-60,left=i%2===0,x=left?12:w-12;sprite(ctx,i%3?13:12,x,y,100+(i%2)*25,!left,Math.sin(i)*.1,.7);}
  const vignette=ctx.createRadialGradient(w/2,h*.44,w*.1,w/2,h*.44,h*.72);vignette.addColorStop(0,'#0000');vignette.addColorStop(1,'#07110cb0');ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);
 }
 function particles(ctx,items){ctx.save();for(const p of items){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.beginPath();ctx.ellipse(p.x,p.y,p.size,p.size*.55,p.life*3,0,Math.PI*2);ctx.fill();}ctx.restore();}
