 function addEnemy(e,kind){const side=e.rng()<.5?-1:1;let x=35+e.rng()*(W-70),y=H+40,vx=0,vy=-(80+e.rng()*35)*(1+e.greed*.13)*e.assist;if(kind==='bat'){x=side<0?-35:W+35;y=130+e.rng()*360;vx=-side*(80+e.greed*9)*e.assist;vy=30;}if(kind==='beetle'){x=side<0?30:W-30;vx=-side*25;}e.objects.push({kind,x,y,baseX:x,vx,vy,r:kind==='beetle'?25:21,hp:kind==='beetle'?2:1,age:0,warn:.65,phase:e.rng()*6.28,gone:false});}
