  if(e.coinClock<=0){const x=90+e.rng()*(W-180);for(let i=0;i<3;i++)e.objects.push({kind:'coin',x:x+Math.sin(i)*35,y:H+25+i*38,vy:-130,r:12,hp:1,age:0,warn:0,phase:i,gone:false});e.coinClock=3.2;}
