document.addEventListener('click',async event=>{const button=event.target.closest('button'),action=button?.dataset.v3;if(!action)return;
 if(action==='privacy')openPrivacy();else if(action==='share-health'||action==='games-only'){const remember=$('privacy-remember').checked;const ok=await v3Action(()=>state.repo.privacy(action==='share-health'));if(ok){storage.set(REMEMBER_KEY,remember?'yes':'no');if(remember&&me())storage.set(SELECTED_KEY,me().id);else storage.remove(SELECTED_KEY);closeDialog('privacy-dialog');if(!me())picker();showToast(action==='share-health'?'Optional nicotine check-ins enabled.':'Games and chat are ready. Nicotine check-ins stay off.');}}
 else if(action==='duel-open')openDuel();
 else if(action==='shift-picker')openShift();else if(action==='shift'){const ok=await v3Action(()=>state.repo.shift(state.selected,button.dataset.shift));if(ok){closeDialog('shift-dialog');showToast('Clocked in for '+SHIFTS[button.dataset.shift][1]+'.');}}
 else if(action==='delete')openDelete(button.dataset.profile);else if(action==='export'){const p=state.profiles.find(p=>p.id===button.dataset.profile);if(!p)return;const ok=await v3Action(async()=>{const data=await state.repo.exportProfile(p.id);const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));link.href=url;link.download='kme-character-export.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});if(ok)showToast('Character data downloaded.');}
 else if(action==='equip'){const ok=await v3Action(()=>state.repo.equip(state.selected,Number(button.dataset.tier)));if(ok)showToast('Cosmetic aura equipped. No gameplay advantage.');}
 else if(action==='forget'){window.KMEArena?.destroy();arenaProfile=null;state.selected=null;storage.remove(SELECTED_KEY);storage.remove(REMEMBER_KEY);closeDialog('privacy-dialog');picker();}
 else if(action==='finale'||action==='arcade'){if(!me()){picker();return;}window.KMEArena?.destroy();arenaProfile=null;state.extractionMode=action==='finale'?'finale':'arcade';navigate('arena');}
 else if(action==='demo-finale'&&!LIVE){const c=state.repo.data.v3.campaign;c.damage=c.max_hp;c.unlocks_at=new Date(Date.now()-1000).toISOString();c.status='finale';state.repo.save();await refreshWorld();renderV3();}
});

// A clock-matched guide. Windows are educational; they do not measure recovery.
const JOURNEY_PHASES=[
 {url:"https://smokefree.gov/quit-vaping-resources/nicotine-withdrawal-vaping",source:"Smokefree",from:0,to:2,title:'The routine is changing.',text:'Your clock has started. You may feel little yet, or an urge may arrive early. Withdrawal and triggers vary between people.'},
 {url:"https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/managing-nicotine-withdrawal-symptoms/",source:"NHS",from:2,to:12,title:'The first shift can be noisy.',text:'Cravings, restlessness or irritability can appear during the early hours. Prepare a distraction and tell the crew what kind of backup helps.'},
 {url:"https://smokefree.gov/quit-vaping-resources/nicotine-withdrawal-vaping",source:"Smokefree",from:12,to:24,title:'One day, one wave at a time.',text:'You are still in the early part of quitting. Concentration, mood, appetite and sleep can feel different. A difficult hour is not a failed attempt.'},
 {url:"https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/managing-nicotine-withdrawal-symptoms/",source:"NHS",from:24,to:72,title:'A commonly difficult window.',text:'Nicotine withdrawal often peaks during the first three days and is commonly toughest in the first week. That is a general pattern, not a promise about your symptoms.'},
 {url:"https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/managing-nicotine-withdrawal-symptoms/",source:"NHS",from:72,to:168,title:'Working through the first week.',text:'Some people start to feel relief; others still have frequent urges. Notice routines and places that trigger yours and keep useful coping tools nearby.'},
 {url:"https://www.nhs.uk/better-health/quit-smoking/staying-smoke-free/managing-nicotine-withdrawal-symptoms/",source:"NHS",from:168,to:672,title:'The volume often eases over weeks.',text:'Withdrawal commonly becomes less intense over the first month. Triggers can still bring urges back. Your actual experience can be faster or slower.'},
 {url:"https://www.cancer.gov/about-cancer/causes-prevention/risk/tobacco/withdrawal-fact-sheet",source:"NCI",from:672,to:Infinity,title:'The long game.',text:'Occasional trigger-related cravings can happen long after quitting. They do not erase your time. If symptoms worry you or fail to improve, speak with a healthcare professional.'}
];
function renderJourneyClock(force=false){if(!$('v3-journey-now'))return;const p=me();if(!p){$('v3-journey-now').innerHTML=empty('Choose your character for a clock-matched journey guide.');return;}if(!clockOn(p)){$('v3-journey-now').innerHTML='<span class="v3-kicker">GAMES-ONLY CHARACTER</span><h2>No nicotine clock is running.</h2><p>Enable optional check-ins in Privacy & data, then enable this character’s quit clock on its employee card. General source-linked guidance remains available below.</p>';return;}
 const ms=streak(p),hours=ms/3600000,phase=JOURNEY_PHASES.find(x=>hours>=x.from&&hours<x.to)||JOURNEY_PHASES.at(-1),key=p.id+':'+phase.from;
 if(force||journeyPhaseKey!==key){journeyPhaseKey=key;$('v3-journey-now').innerHTML='<span class="v3-kicker">MATCHED TO YOUR ACTUAL LOGGED CLOCK</span><div class="journey-clock" id="v3-journey-clock"></div><span class="timeline-window">'+(Number.isFinite(phase.to)?phase.from+'–'+phase.to+' HOURS':'28 DAYS AND ONWARD')+'</span><h2>'+phase.title+'</h2><p>'+phase.text+'</p><div class="progress-track"><div class="progress-fill" id="v3-journey-progress"></div></div><p class="timeline-next" id="v3-journey-next"></p><p class="v3-note">Based on your quit start or latest logged nicotine use, whichever is later. This is self-reported time—not a test of nicotine levels, a health score, or a medical forecast. <a href="'+phase.url+'" target="_blank" rel="noopener noreferrer">'+phase.source+' withdrawal guide ↗</a></p>';}
 const t=timeParts(ms);$('v3-journey-clock').textContent=t.days+'d '+String(t.hours).padStart(2,'0')+'h '+String(t.minutes).padStart(2,'0')+'m '+String(t.seconds).padStart(2,'0')+'s';$('v3-journey-progress').style.width=(Number.isFinite(phase.to)?Math.min(100,(hours-phase.from)/(phase.to-phase.from)*100):100)+'%';$('v3-journey-next').textContent=Number.isFinite(phase.to)?'Next information window in '+secondsLabel((phase.to-hours)*3600)+'. This bar measures time, not recovery.':'Keep your coping plan available. Your clock continues; the app does not predict symptoms.';
}

