/* Rotating arcade proposals; the developer builds the winner every two days. */
const V4_CHOICES=[{key:'rooftop-rat-race',name:'Rooftop Rat Race',pitch:'Escape the kiosk across neon rooftops with a briefcase full of terrible decisions.',mechanic:'Double-jump, wall-kick and grind rails. Choose risky shortcuts to build a combo.',art:0},{key:'swamp-delivery',name:'Swamp Delivery Service',pitch:'Get the crew their emergency snacks before the swamp eats your company van.',mechanic:'Steer a drifting boat, plan delivery routes and dodge hungry monsters.',art:1},{key:'pouch-poltergeist',name:'Pouch Poltergeist',pitch:'The office is haunted by your former subscriptions. Evict them with a vacuum.',mechanic:'Aim the suction beam, manage an overheating tank and throw captured ghosts at the boss.',art:2}];
const v4Ready=()=>state.world?.version>=4;let urgeInstance=null,closingUrge=false;
function demoBallot(choices=V4_CHOICES){return {id:uid(),opened_at:new Date().toISOString(),closes_at:new Date(Date.now()+48*3600000).toISOString(),choices:structuredClone(choices),status:'open',winner_key:null,votes:[]};}
const v4DemoWorld=DemoRepository.prototype.world;
DemoRepository.prototype.world=async function(){const base=await v4DemoWorld.call(this),d=this.data;d.v4??={current:{game_key:'smoke-break',game_name:'Smoke Break: Extraction',build:'4.0.0'},ballot:demoBallot(),empty:null,relief:{},deviceRelief:{hits:0,damage:0},runs:[],scores:{}};const v=d.v4,b=v.ballot;if(b.status==='open'&&Date.now()>=Date.parse(b.closes_at)){if(!b.votes.length){v.empty=b.closes_at;v.ballot=demoBallot(b.choices);}else{b.status='awaiting_build';b.winner_key=b.choices.map((c,i)=>({key:c.key,n:b.votes.filter(v=>v.key===c.key).length,i})).sort((a,b)=>b.n-a.n||a.i-b.i)[0].key;}}
 const ballot=v.ballot,day=utcDay();if(v.deviceRelief.day!==day)v.deviceRelief={day,hits:0,damage:0};this.save();return {...base,version:4,arcade:{current:v.current,ballot:{...ballot,choices:ballot.choices.map(c=>({...c,votes:ballot.votes.filter(v=>v.key===c.key).length})),my_vote:ballot.votes[0]?{key:ballot.votes[0].key,profile_id:ballot.votes[0].profile_id}:null,total_votes:ballot.votes.length},last_empty_round:v.empty,scores:base.extraction.map(s=>({profile_id:s.profile_id,game_key:'smoke-break',best:s.best,extracts:s.extracts})),relief:d.profiles.map(p=>{const s=v.relief[p.id+'-'+day]||{hits:0,damage:0};return {profile_id:p.id,...s,remaining:Math.max(0,Math.min(10-s.damage,10-v.deviceRelief.damage))};})}};};
DemoRepository.prototype.arcadeVote=async function(id,ballotId,key){await this.world();const b=this.data.v4.ballot;if(b.id!==ballotId||b.status!=='open'||Date.now()>=Date.parse(b.closes_at))throw Error('This ballot closed. Refresh for the next round.');if(!b.choices.some(c=>c.key===key))throw Error('Choose one of the proposals.');const prior=b.votes[0];if(prior&&prior.profile_id!==id)throw Error('This device already voted as another character. Switch back to change it.');b.votes=[{profile_id:id,key}];this.save();return {ok:true};};
DemoRepository.prototype.arcadeStart=async function(id,mode,key){if(key!==this.data.v4.current.game_key)throw Error('The arcade changed. Refresh.');return {...await this.extractionStart(id,mode),game_key:key};};
DemoRepository.prototype.reliefStart=async function(id){await this.world();const v=this.data.v4,previous=v.runs.findLast(r=>r.profile_id===id&&!r.result&&Date.now()-r.started<300000);if(previous)return {id:previous.id,seed:previous.seed};const r={id:uid(),profile_id:id,seed:Math.floor(Math.random()*2147483647),started:Date.now(),campaign_id:this.data.v3.campaign.id};v.runs.push(r);this.save();return {id:r.id,seed:r.seed};};
DemoRepository.prototype.reliefBank=async function(id,hits){const v=this.data.v4,r=v.runs.find(r=>r.id===id);if(!r)throw Error('Unknown game receipt.');if(r.result)return r.result;if(hits<0||hits>60||hits>Math.floor(Math.min(90,(Date.now()-r.started)/1000)/.7))throw Error('That action count exceeds the game time.');const day=utcDay(r.started),d=v.relief[r.profile_id+'-'+day]??={hits:0,damage:0},u=v.deviceRelief;if(u.day!==day){u.day=day;u.hits=0;u.damage=0;}const n=Math.max(0,Math.min(hits,30-d.hits,30-u.hits)),earned=Math.min(Math.floor((d.hits+n)/3)-Math.floor(d.hits/3),Math.floor((u.hits+n)/3)-Math.floor(u.hits/3)),c=this.data.v3.campaign;let damage=0;if(c.id===r.campaign_id&&['wearing','sealed'].includes(c.status)&&c.members.some(m=>m.profile_id===r.profile_id))damage=Math.max(0,Math.min(earned,10-d.damage,10-u.damage));d.hits+=n;u.hits+=n;d.damage+=damage;u.damage+=damage;c.damage+=damage;r.result={ok:true,hits,fragments_banked:n,fragments_today:d.hits,damage,damage_today:d.damage,daily_damage_left:Math.max(0,Math.min(10-d.damage,10-u.damage)),next_fragment:d.hits%3,game_only:true};this.save();return r.result;};
LiveRepository.prototype.arcadeVote=function(id,ballot,key){return liveRpc(this,'kme_arcade_vote',{p_profile_id:id,p_ballot_id:ballot,p_choice_key:key});};
LiveRepository.prototype.arcadeStart=function(id,mode,key){return liveRpc(this,'kme_arcade_start',{p_profile_id:id,p_mode:mode,p_game_key:key});};
LiveRepository.prototype.reliefStart=function(id){return liveRpc(this,'kme_relief_start',{p_profile_id:id});};
LiveRepository.prototype.reliefBank=function(id,hits){return liveRpc(this,'kme_relief_bank',{p_run_id:id,p_hits:hits});};
const v4ExportDemo=DemoRepository.prototype.exportProfile;DemoRepository.prototype.exportProfile=async function(id){return {...await v4ExportDemo.call(this,id),arcade_vote:this.data.v4?.ballot.votes.filter(v=>v.profile_id===id)||[],relief_runs:this.data.v4?.runs.filter(r=>r.profile_id===id)||[]};};
const v4DeleteDemo=DemoRepository.prototype.deleteProfile;DemoRepository.prototype.deleteProfile=async function(id,name){await v4DeleteDemo.call(this,id,name);if(this.data.v4){this.data.v4.ballot.votes=this.data.v4.ballot.votes.filter(v=>v.profile_id!==id);this.data.v4.runs=this.data.v4.runs.filter(r=>r.profile_id!==id);for(const key of Object.keys(this.data.v4.relief))if(key.startsWith(id+'-'))delete this.data.v4.relief[key];this.save();}};

function arcadeKey(){return state.world?.arcade?.current?.game_key||'smoke-break';}
const arcadeHost={game:null,destroy(){this.game?.destroy();this.game=null;}};window.KMEArena=arcadeHost;window.KMEArcadeHost=arcadeHost;
mountArena=function(){if(!me()||!v3Ready()){arcadeHost.destroy();$('arena-game').innerHTML=empty('Choose your character to enter the arcade.');return;}const gameKey=arcadeKey(),mode=state.extractionMode,key=state.selected+':'+mode+':'+gameKey;if(arenaProfile===key)return;arcadeHost.destroy();const game=window.KMEGames.registry[gameKey];if(!game){$('arena-game').innerHTML='<div class="v4-update-required"><h2>A new game just landed.</h2><p>Refresh to download '+esc(state.world.arcade.current.game_name)+'. Your rewards are saved.</p><button class="button" data-v4="reload">Refresh arcade ↻</button></div>';arenaProfile=null;return;}const player=me(),repo=state.repo;arcadeHost.game=game;game.mount($('arena-game'),{profile:player,mode,gameKey,onStart:()=>v4Ready()?repo.arcadeStart(player.id,mode,gameKey):repo.extractionStart(player.id,mode),onPulse:(id,nonce)=>repo.extractionPulse(id,nonce),onFinish:async(id,score,greed,capsules,extract)=>{const result=await repo.extractionFinish(id,score,greed,capsules,extract);state.version++;await refreshWorld();return result;},onCancel:id=>repo.extractionFinish(id,0,0,0,false)});arenaProfile=key;};
const v4OldScores=renderV3Scores;renderV3Scores=function(){if(!v4Ready())return v4OldScores();const entries=(state.world.arcade.scores||[]).filter(s=>s.game_key===arcadeKey()&&s.extracts>0).sort((a,b)=>b.best-a.best);$('arena-scores').innerHTML=entries.length?'<table class="scoreboard"><thead><tr><th>#</th><th>GOBLIN</th><th>BEST HAUL</th></tr></thead><tbody>'+entries.map((s,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(state.profiles.find(p=>p.id===s.profile_id)?.name||'Former employee')+'</td><td>'+s.best+'</td></tr>').join('')+'</tbody></table>':empty('This game has a fresh leaderboard. Bank a run to join it.');};
const v4OldDecorate=renderV3;renderV3=function(){v4OldDecorate();renderV4();};const v4OldTimers=renderTimers;renderTimers=function(){v4OldTimers();renderBallotClock();};const v4OldBusy=setBusy;setBusy=function(value){v4OldBusy(value);const b=document.querySelector('[data-action="craving"]');if(b)b.disabled=value||!me()||!v4Ready();};
function renderBallotClock(){const b=state.world?.arcade?.ballot,el=$('v4-vote-clock');if(!el||!b)return;const seconds=Math.max(0,(Date.parse(b.closes_at)-groupNow())/1000),hours=Math.floor(seconds/3600);el.textContent=b.status==='awaiting_build'?'VOTE CLOSED · WINNER QUEUED':seconds>0?hours+'h '+Math.floor(seconds%3600/60)+'m left':'ROUND CLOSING · REFRESH TO CHECK';}
function renderV4(){if(!$('v4-ballot'))return;const room=state.world?.arcade,b=room?.ballot,p=me();$('v3-summary').textContent='KME v4 · '+(LIVE?'PRIVATE FRIENDS GROUP':'ISOLATED DEMO')+' · THE ROTATING ARCADE';const craving=document.querySelector('[data-action="craving"]');if(craving)craving.disabled=state.busy||!p||!v4Ready();$('v4-live-title').textContent=room?.current?.game_name||'Smoke Break: Extraction';
 const relief=room?.relief?.find(x=>x.profile_id===p?.id);$('v4-relief-left').textContent=relief?relief.remaining+' bonus boss damage left today · '+relief.hits%3+'/3 fragments toward next chip':'Tiny sessions. Bank whenever.';
 if(!b){$('v4-ballot').innerHTML='<div class="v4-vote-intro"><span class="v3-kicker">THE NEXT ARCADE NEEDS ITS DATABASE UPDATE</span><h2>Three ideas. One next game.</h2><p>The illustrated arcade works now. Run the rotating-arcade migration to enable group voting and bankable Urge Breaker rewards.</p></div>';return;}
 const winner=b.choices.find(c=>c.key===b.winner_key),canVote=p&&b.status==='open'&&(!b.my_vote||b.my_vote.profile_id===p.id);$('v4-ballot').innerHTML='<div class="v4-vote-intro"><div><span class="v3-kicker">YOU PICK THE NEXT GAME · 48-HOUR VOTE</span><h2>What should the goblins build?</h2><p>These are proposals for the next build. The current game stays playable while the winner is developed.</p></div><span class="v4-vote-clock" id="v4-vote-clock"></span></div>'+(winner?'<div class="v4-winner"><strong>'+esc(winner.name)+' won.</strong> Voting is closed. It joins the arcade after its build and deployment are finished.</div>':'')+'<div class="v4-ballot-grid">'+b.choices.map((c,i)=>'<article class="v4-proposal '+(b.my_vote?.key===c.key?'voted':'')+'"><div class="v4-concept v4-concept-'+i+'" aria-hidden="true"><span>PROPOSAL 0'+(i+1)+'</span><canvas width="380" height="170" data-concept="'+i+'"></canvas></div><div class="v4-proposal-copy"><h3>'+esc(c.name)+'</h3><p>'+esc(c.pitch)+'</p><p class="v4-mechanic">'+esc(c.mechanic)+'</p><div class="v4-proposal-vote"><span>'+c.votes+' '+(c.votes===1?'vote':'votes')+'</span><button class="button secondary" data-v4="vote" data-choice="'+esc(c.key)+'" '+(!canVote||v3MutationBusy?'disabled':'')+'>'+(b.my_vote?.key===c.key?'Your vote ✓':'Vote for this')+'</button></div></div></article>').join('')+'</div><p class="v4-ballot-note">One vote per character and device. Change it until closing. Ties go to the first-listed tied proposal. '+(b.my_vote&&b.my_vote.profile_id!==p?.id?'This device already voted as '+esc(state.profiles.find(p=>p.id===b.my_vote.profile_id)?.name||'another character')+'. Switch back to change it. ':'')+'No votes = no game change; the same proposals get another 48-hour window.</p>'+(room.last_empty_round?'<p class="v4-ballot-note">The previous round had no votes. The arcade stayed exactly where it was.</p>':'');renderBallotClock();drawConcepts();}
function drawConcepts(){const draw=()=>{for(const canvas of document.querySelectorAll('[data-concept]')){const ctx=canvas.getContext('2d'),i=Number(canvas.dataset.concept);KMEArt.background(ctx,380,170,i*4);if(i===0){ctx.fillStyle='#344237';ctx.beginPath();ctx.moveTo(0,150);ctx.lineTo(100,115);ctx.lineTo(190,144);ctx.lineTo(300,88);ctx.lineTo(380,105);ctx.lineTo(380,170);ctx.lineTo(0,170);ctx.fill();KMEArt.sprite(ctx,1,190,91,130);KMEArt.sprite(ctx,9,290,55,42);}else if(i===1){ctx.fillStyle='#66b9a030';ctx.fillRect(0,90,380,80);ctx.strokeStyle='#b38a5b';ctx.lineWidth=14;ctx.beginPath();ctx.ellipse(205,125,77,15,-.07,0,Math.PI);ctx.stroke();KMEArt.sprite(ctx,0,200,85,100);KMEArt.sprite(ctx,14,55,65,120);KMEArt.sprite(ctx,6,330,65,80);}else{KMEArt.sprite(ctx,14,70,90,170);KMEArt.sprite(ctx,0,195,100,110);KMEArt.sprite(ctx,4,300,74,120);ctx.strokeStyle='#9bddcd';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(220,100);ctx.quadraticCurveTo(280,130,300,75);ctx.stroke();}}};draw();KMEArt.ready.then(draw);}
function reliefReceiptKey(){return 'kme-relief-receipt-'+(LIVE?CONFIG.supabaseUrl:'demo')+'-'+state.selected;}
function openQuick(){if(!me()){picker();return;}if(!v4Ready()){showToast('The rotating-arcade database update is needed first.');return;}const player=me(),repo=state.repo,key=reliefReceiptKey(),owner=repo.userId||'demo';let receipt=null;try{const saved=JSON.parse(storage.get(key)||'null');if(saved?.owner===owner)receipt=saved;}catch{}arcadeHost.destroy();arenaProfile=null;showDialog('urge-dialog');$('urge-character').textContent=player.name;urgeInstance=KMEUrge.mount($('urge-mount'),{receipt,onStart:()=>repo.reliefStart(player.id),onReceipt:r=>{if(r)storage.set(key,JSON.stringify({...r,owner}));else storage.remove(key);},onBank:async(id,hits)=>{const result=await repo.reliefBank(id,hits);state.version++;await refreshWorld();return result;}});$('urge-log').disabled=!healthAllowed()||!clockOn(player);$('urge-log').textContent='Optional: log a craving for the crew';}
