for(let i=0;i<s.relays.length;i++){const r=s.relays[i],m=get('r'+i,()=>{const g=new T.Group();scene.add(g);mesh('cyl',0x394b52,0,.5,0,.65,1,.65,g);mesh('sphere',0xf2aa6a,0,1.25,0,.35,.55,.35,g,true);ring(0,0,1.8,0xe9b770,g);return g;});m.position.set(r.x,0,r.z);m.children[1].material=mat(r.on?0xffb96a:0x487d6f,true);m.children[1].rotation.y=s.time;m.children[2].visible=r.on;}
for(const z of s.zones){const m=get('z'+z.id,()=>ring(0,0,z.r,z.kind==='plasma'?0x92e1de:z.kind==='sludge'?0xb3bd69:0xf7af7b));m.position.set(z.x,.08,z.z);m.scale.setScalar(z.r*(z.age<z.warn?.5+z.age/z.warn*.5:1));}
for(const d of s.drops){const m=get('d'+d.id,()=>mesh('sphere',d.kind==='heal'?0x88ffc5:d.kind==='capsule'?0xceb1ff:0xf7c777,0,.5,0,.22,.3,.22,scene,true));m.position.set(d.x,.55+Math.sin(s.time*4+d.id)*.14,d.z);m.rotation.y=s.time*2;}
for(let j=0;j<s.effects.length;j++){const fx=s.effects[j];if(['burrow-dust','eruption','impact','shield-spark'].includes(fx.kind))continue;if(fx.kind==='arc'){const m=get('arc'+j+fx.x+fx.z,()=>mesh('box',0xa9e9ed,0,1,0,.08,.08,1,scene,true));m.position.set((fx.x+fx.tx)/2,1,(fx.z+fx.tz)/2);m.scale.z=Math.hypot(fx.tx-fx.x,fx.tz-fx.z);m.rotation.y=Math.atan2(fx.tx-fx.x,fx.tz-fx.z);continue;}const m=get('fx'+j+fx.x+fx.z,()=>ring(0,0,1,fx.kind==='pulse'?0xb6f9f4:0xffc59b));m.position.set(fx.x,.4,fx.z);m.scale.setScalar(fx.kind==='pulse'?(1-fx.life/.45)*3.2:1-fx.life);}
