function frame(now){if(!alive||!active)return;if(document.hidden){bank(false);return;}tick(e,Math.min(.25,(now-last)/1000));last=now;draw(ctx,e);clock();$('.urge-clock').textContent=Math.floor(e.elapsed)+'s · '+e.score+' points';$('.urge-progress').textContent=e.hits+' hits · '+e.strikes+'/5 mistakes';controls();if(e.status==='done'){bank(false);return;}raf=requestAnimationFrame(frame);}
