// The first two visits offer Tweakmax; every third suggests a drawing. Either is selectable.
let quickChoiceMount=null,quickLifecycle=0;
openQuick=function(){if(!me()){picker();return;}if($('urge-dialog').open)return;if(!v4Ready()){showToast('The group connection is not ready.');return;}const lifecycle=quickLifecycle,player=me(),repo=state.repo,key=reliefReceiptKey(),owner=repo.userId||'demo',timerKey=holdKey(),draftKey='kme-drawing-'+owner+'-'+player.id;let receipt=null;try{const r=JSON.parse(storage.get(key)||'null');if(r?.owner===owner)receipt=r;}catch{}if(!readHold())setHoldMinutes(3);else restoreHold();arcadeHost.destroy();arenaProfile=null;showDialog('urge-dialog');$('urge-character').textContent=player.name;let bar=$('urge-mode-bar');if(!bar){bar=document.createElement('div');bar.id='urge-mode-bar';bar.className='urge-mode-bar';bar.innerHTML='<button data-urge-choice="game">Play Tweakmax</button><button data-urge-choice="drawing">Draw a side quest</button>';$('urge-mount').before(bar);}const timeOptions={timerRemaining:()=>{try{return Math.max(0,(JSON.parse(storage.get(timerKey)||'null')?.until||0)-Date.now());}catch{return 0;}},setMinutes:n=>{if(state.selected===player.id&&[3,5].includes(n))setHoldMinutes(n);}};
let choosing=false;async function choose(mode){if(choosing)return;choosing=true;try{if(urgeInstance){if(await urgeInstance.bank(false)===false)return;urgeInstance.destroy();}KMEDrawing.destroy();for(const b of bar.querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.urgeChoice===mode));if(mode==='drawing'){urgeInstance=KMEDrawing.mount($('urge-mount'),{...timeOptions,id:uid,loadDraft:()=>{try{return JSON.parse(storage.get(draftKey)||'null');}catch{return null;}},saveDraft:d=>d?storage.set(draftKey,JSON.stringify(d)):storage.remove(draftKey),onSubmit:async r=>{if(repo!==state.repo||state.selected!==player.id)throw Error('Switch back to the drawing’s character first.');const result=chatResult(await repo.chatDrawing(player.id,r.id,r.prompt,r.png,r.resisted));if(lifecycle!==quickLifecycle)return result;if(result.resisted_logged)clearHold();chatAt=0;chatRevision=null;state.version++;await refreshWorld();return result;},viewChat:async()=>{await closeQuick();navigate('lounge');chatLoad(false,true);}});}else urgeInstance=KMEUrge.mount($('urge-mount'),{...timeOptions,receipt,onStart:()=>repo.reliefStart(player.id),onReceipt:r=>{receipt=r;if(r)storage.set(key,JSON.stringify({...r,owner}));else storage.remove(key);},canResist:()=>!!me()&&state.selected===player.id&&healthAllowed()&&clockOn(me()),onBank:async(id,hits,score,resisted)=>{const r=await repo.reliefFinish(id,hits,score,resisted);state.version++;if(r.resisted_logged){clearHold();await refresh(true);}else await refreshWorld();return r;}});}finally{choosing=false;}}
quickChoiceMount=choose;const counterKey='kme-quick-visits-'+owner+'-'+player.id,n=(Number(storage.get(counterKey)||0)+1);storage.set(counterKey,String(n));bar.querySelector('[data-urge-choice="drawing"]').disabled=!chatReady();choose(!receipt&&chatReady()&&n%3===0?'drawing':'game');$('urge-log').disabled=!healthAllowed()||!clockOn(player);$('urge-log').textContent='Optional: log a craving for the crew';};
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-urge-choice]');if(b)quickChoiceMount?.(b.dataset.urgeChoice);});
